public int nameLength(Map<String,String> users, String id) {
    String name = users.get(id);   // returns null if id is absent
    return name.length();          // NPE here: "name" is null
}
// Trace: Cannot invoke "String.length()" because "name" is null
//        at com.app.UserService.nameLength(UserService.java:12)
